def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_threats += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive:
        return float(min(budget, 5.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if supply <= 17:
        urgency += 2
    elif supply <= 19:
        urgency += 1
    if day >= 8 and hp <= 5:
        urgency += 1

    pressure = 0
    if highest_prev >= 130:
        pressure += 3
    elif highest_prev >= 100:
        pressure += 2
    elif highest_prev >= 70:
        pressure += 1
    pressure += min(rich_threats, 2)
    pressure += min(desperate_threats, 2)

    if urgency >= 7:
        bid = max(95.0, highest_prev + 3.0)
    elif urgency >= 5:
        bid = max(72.0, avg_prev + 6.0, highest_prev * 0.78)
    elif urgency >= 3:
        if highest_prev >= 120 and hp > 4 and no_water_days == 0 and supply >= 20:
            bid = 18.0
        else:
            bid = max(38.0, avg_prev * 0.55 + 6.0)
    else:
        if supply >= 22 and highest_prev >= 100:
            bid = 8.0
        elif supply >= 20:
            bid = 16.0 + 6.0 * (1.0 - supply_ratio)
        else:
            bid = 24.0 + 10.0 * (1.0 - supply_ratio)

    if pressure >= 5 and urgency <= 2:
        bid *= 0.7
    elif pressure >= 4 and urgency <= 4:
        bid *= 0.85

    reserve = 0.0
    if hp <= 3 or no_water_days >= 1:
        reserve = 0.0
    else:
        reserve = 35.0
    max_safe = max(0.0, budget - reserve)
    if max_safe <= 0:
        max_safe = budget

    if day == 1 and hp >= 8 and supply >= 20:
        bid = min(bid, 22.0)

    bid = min(bid, max_safe)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    supply = float(day_context['supply'])
    day = day_context['day']

    # Extract yesterday bids for immediate pressure reaction
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
            prev_hp_after.append(float(prev.get('hp_after', opp.get('hp', 0))))

    # If we have no trace info, use conservative baseline
    if not prev_bids:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    highest_prev_bid = max(prev_bids)
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Tight supply => more likely someone will fight; loosen when supply is abundant
    # supply is between 15 and 25; compare to 2*WATER_REQ=18 as a pivot
    tight = supply < (2.0 * WATER_REQ)

    # Decide bid aggressiveness
    # If someone already paid near our salary scale, we only need to slightly beat them when tight.
    # Otherwise, bid around the lower of (just above second-highest) and a cap tied to salary.
    if tight:
        # If yesterday's highest bid was very high, don't fully match; bid just above second-highest.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = second_prev_bid + 1.0
        else:
            target = highest_prev_bid + 1.0
    else:
        # Abundant supply: avoid bidding into arms race; bid near second-highest.
        target = min(highest_prev_bid, second_prev_bid + 0.5)

    # HP-aware adjustment: if we're healthy, be less aggressive; if low, increase.
    hp = float(my_status.get('hp', 0))
    if hp <= 2:
        cap = DAILY_SALARY * 0.95
        target = max(target, DAILY_SALARY * 0.75)
    elif hp <= 4:
        cap = DAILY_SALARY * 0.85
        target = max(target, DAILY_SALARY * 0.6)
    else:
        cap = DAILY_SALARY * 0.7

    # Ensure we don't exceed budget
    bid = min(float(my_status['budget']), min(cap, float(target)))

    # If budget is too low, still bid at least a minimal fraction to avoid wasting chance.
    # Minimal bid scales with need and supply tightness.
    min_bid = DAILY_SALARY * (0.25 if not tight else 0.35)
    if bid < min_bid:
        bid = min(float(my_status['budget']), min_bid)

    # Final sanity: non-negative
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid strategy based on urgency and supply
    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
        # Very critical, bid aggressively to survive
        current_bid = DAILY_SALARY * 0.95
    else:
        # Not critical, adjust bid based on supply scarcity
        if day_context['supply'] < WATER_REQ * 1.5: # Supply is tight (e.g., 15-19 for WATER_REQ=13)
            current_bid = DAILY_SALARY * 0.8 # Aggressive base bid (120)
        else: # Supply is moderately available (e.g., 20-25 for WATER_REQ=13)
            current_bid = DAILY_SALARY * 0.7 # Moderate base bid (105)

    # Further adjust bid based on opponent's previous bids to stay competitive
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85: # Opponents were bidding very high
            current_bid = max(current_bid, highest_prev_bid + 2.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.6: # Opponents were bidding moderately high
            current_bid = max(current_bid, highest_prev_bid + 1.0)
        else: # Opponents bid low, try to win cheaply but surely
            current_bid = max(current_bid, highest_prev_bid + 0.5)

    # Ensure bid doesn't exceed current budget
    return min(my_status['budget'], current_bid)

